// Credits for Wikimedia Commons photos, generated by scripts/build-photo-credits.mjs
// from Commons metadata (never written by hand). Rerun the script after adding
// or replacing a photo.
import data from "@/content/species/photo-credits.json";

export interface PhotoCredit {
  subject?: string;
  /** The photo's own title, for photos credited "Title" by Author. */
  title?: string | null;
  file: string;
  page: string;
  artist: string | null;
  licence: string | null;
  licenceUrl: string | null;
}

interface CreditData {
  photos: Record<string, PhotoCredit>;
  wikipedia: Record<string, PhotoCredit & { src: string }>;
  unmatched: { src: string; reason: string }[];
}

const credits = data as unknown as CreditData;

/** Credit for a photo stored in the repo, by its public path. */
export function creditFor(src: string): PhotoCredit | null {
  return credits.photos[src] ?? null;
}

/** The Commons file (960 px thumbnail) and credit for a Wikipedia article's lead photo. */
export function wikipediaHero(title: string): (PhotoCredit & { src: string }) | null {
  return credits.wikipedia[title] ?? null;
}

export function allPhotoCredits(): Record<string, PhotoCredit> {
  return credits.photos;
}
